by_date_courtroom_time.map:
function (doc) {
  if (doc.type === 'hearing' && doc.date && doc.courtroom && doc.start_time) {
    emit([doc.date, doc.courtroom, doc.start_time, doc.judge, doc.case_number], {
      id: doc._id,
      judge: doc.judge,
      case_number: doc.case_number,
      case_title: doc.case_title,
      matter: doc.matter,
      movant: doc.movant || null,
      trustee: doc.trustee || null,
      status: doc.status || 'scheduled'
    });
  }
}

