lists.nested_calendar:
function (head, req) {
  var row;
  var result = {
    date: null,
    timezone: 'America/Denver',
    court: 'U.S. Bankruptcy Court, District of Utah',
    sessions: []
  };
  var sessions = {};

  while ((row = getRow())) {
    var key = row.key;
    var val = row.value;
    var date = key[0];
    var courtroom = key[1];
    var start_time = key[2];
    var judge = key[3];
    var case_number = key[4];

    if (!result.date) result.date = date;

    if (!sessions[courtroom]) {
      sessions[courtroom] = { courtroom: courtroom, slots: {} };
    }
    var room = sessions[courtroom];

    if (!room.slots[start_time]) {
      room.slots[start_time] = { start_time: start_time, judges: {} };
    }
    var slot = room.slots[start_time];

    if (!slot.judges[judge]) {
      slot.judges[judge] = { judge: judge, cases: {} };
    }
    var j = slot.judges[judge];

    if (!j.cases[case_number]) {
      j.cases[case_number] = {
        case: { number: case_number, title: val.case_title },
        matters: []
      };
    }
    j.cases[case_number].matters.push({
      id: val.id,
      matter: val.matter,
      movant: val.movant,
      trustee: val.trustee,
      status: val.status
    });
  }

  Object.keys(sessions).sort().forEach(function (roomName) {
    var room = sessions[roomName];
    var slotsArr = Object.keys(room.slots).sort().map(function (t) {
      var slot = room.slots[t];
      slot.judges = Object.keys(slot.judges).sort().map(function (jn) {
        var j = slot.judges[jn];
        j.cases = Object.keys(j.cases).map(function (cn) { return j.cases[cn]; });
        return j;
      });
      return slot;
    });
    room.slots = slotsArr;
    result.sessions.push(room);
  });

  send(JSON.stringify(result, null, 2));
}

filters.hearings_by_date:
function (doc, req) {
  if (doc.type !== 'hearing') return false;
  if (req.query.date && doc.date !== req.query.date) return false;
  return true;
}
